using System;using System.Collections.Concurrent;using System.IO;using System.Linq;using System.Diagnostics;using System.Collections.Generic;using System.Text;using System.Text.RegularExpressions;
namespace PZ3D {
 sealed class LauncherTaskEvent {public string at,message;public int progress;}
 sealed class LauncherTaskRecord {public string id,action,title,started,finished,status,message;public int progress=-1,ownerPid;public long ownerBirth;public List<LauncherTaskEvent> events=new List<LauncherTaskEvent>();}
 sealed class LauncherTaskStore {public int version=1;public List<LauncherTaskRecord> history=new List<LauncherTaskRecord>();}
 sealed class LauncherJournal {
  readonly string file,logFile;string activeId;
  // A task result must not depend on diagnostic disk IO. Pending records are shared
  // by controllers for this file and retried on the next journal write, not by a timer.
  static readonly ConcurrentDictionary<string,LauncherTaskStore> Pending=new ConcurrentDictionary<string,LauncherTaskStore>(StringComparer.OrdinalIgnoreCase);
  static readonly ConcurrentDictionary<string,string> LogWarnings=new ConcurrentDictionary<string,string>(StringComparer.OrdinalIgnoreCase);
  public LauncherJournal(string data){file=Path.Combine(data,"diagnostics","tasks.json");logFile=Path.Combine(data,"diagnostics","launcher.log");LauncherNativeState.Locked(file,()=>{var s=Read();bool changed=false;foreach(var task in s.history.Where(t=>t.status=="running")){if(!OwnerAlive(task)){task.status="interrupted";task.finished=DateTime.UtcNow.ToString("o");task.message="上次任务中断；实际文件状态请在对应页面刷新核对。";changed=true;}}if(changed)Save(s);return true;});}
  LauncherTaskStore ReadDisk(){var s=LauncherNativeState.Read(file,()=>new LauncherTaskStore());if(s==null||s.version!=1||s.history==null||s.history.Count>60||s.history.Any(t=>t==null||t.events==null||t.events.Count>120))throw new InvalidDataException("任务记录无效，未覆盖。");return s;}
  LauncherTaskStore Read(){LauncherTaskStore cached;if(!Pending.TryGetValue(file,out cached))return ReadDisk();try{cached=Merge(ReadDisk(),cached);Pending[file]=cached;}catch(IOException){}catch(UnauthorizedAccessException){}catch(InvalidDataException){}return cached;}
  static string LastChange(LauncherTaskRecord task){return new[]{task.started,task.finished}.Concat(task.events.Select(e=>e.at)).Where(value=>value!=null).OrderByDescending(value=>value,StringComparer.Ordinal).FirstOrDefault()??"";}
  static LauncherTaskStore Merge(LauncherTaskStore disk,LauncherTaskStore pending){var records=new Dictionary<string,LauncherTaskRecord>(StringComparer.Ordinal);foreach(var row in disk.history.Concat(pending.history)){LauncherTaskRecord prior;if(!records.TryGetValue(row.id,out prior)||prior.status=="running"&&row.status!="running"||((prior.status=="running")== (row.status=="running")&&StringComparer.Ordinal.Compare(LastChange(row),LastChange(prior))>=0))records[row.id]=row;}return new LauncherTaskStore{history=records.Values.OrderByDescending(row=>row.started,StringComparer.Ordinal).Take(50).ToList()};}
  static bool OwnerAlive(LauncherTaskRecord r){try{using(var p=Process.GetProcessById(r.ownerPid))return !p.HasExited&&p.StartTime.ToUniversalTime().Ticks==r.ownerBirth;}catch{return false;}}
  public static string Sanitize(string text){string clean=ScrubText(text??"",0);return new string(clean.Where(c=>!char.IsControl(c)||c=='\n'||c=='\t').Take(4000).ToArray());}
  static readonly Regex SensitiveKey=new Regex(@"(?i)^(password|passwd|userPassword|serverPassword|token|ticket|authorization|userCipher|serverCipher)$");
  static object ScrubObject(object value,int depth){if(depth>8)return "[深层内容已隐藏]";var map=value as Dictionary<string,object>;if(map!=null){var safe=new Dictionary<string,object>();foreach(var p in map)safe[p.Key]=SensitiveKey.IsMatch(p.Key)?"[已隐藏]":ScrubObject(p.Value,depth+1);return safe;}var array=value as object[];if(array!=null)return array.Select(v=>ScrubObject(v,depth+1)).ToArray();if(value is string)return ScrubText((string)value,depth+1);return value;}
  static string ScrubText(string text,int depth){if(depth>8)return "[深层内容已隐藏]";if(text.Length>65536)text=text.Substring(0,65536);string trim=text.TrimStart();if(trim.StartsWith("{")||trim.StartsWith("[")){try{var j=new System.Web.Script.Serialization.JavaScriptSerializer{MaxJsonLength=65536,RecursionLimit=24};return j.Serialize(ScrubObject(j.DeserializeObject(text),depth+1));}catch{}}
   text=Regex.Replace(text,@"(?i)(password|passwd|userPassword|serverPassword|token|ticket|authorization|userCipher|serverCipher)(?:\\*[""'])?\s*[=:][^\r\n]*","$1=[已隐藏]");return Regex.Replace(text,@"(?i)(connect|login)\s+[^\r\n]*","$1 [连接参数已隐藏]");}
  public string Begin(string action,string title){return LauncherNativeState.Locked(file,()=>{var s=Read();using(var p=Process.GetCurrentProcess()){var r=new LauncherTaskRecord{id=Guid.NewGuid().ToString("N"),action=Sanitize(action),title=Sanitize(title),started=DateTime.UtcNow.ToString("o"),status="running",message="正在准备",ownerPid=p.Id,ownerBirth=p.StartTime.ToUniversalTime().Ticks};s.history.Insert(0,r);s.history=s.history.Take(50).ToList();activeId=r.id;Save(s);Append(r.title+" · 开始");return r.id;}});}
  public void Update(int progress,string message){if(activeId==null)return;LauncherNativeState.Locked(file,()=>{var s=Read();var r=s.history.FirstOrDefault(x=>x.id==activeId);if(r==null||r.status!="running")return false;r.progress=progress<0?-1:Math.Min(100,progress);r.message=Sanitize(message);r.events.Add(new LauncherTaskEvent{at=DateTime.UtcNow.ToString("o"),progress=r.progress,message=r.message});r.events=r.events.Skip(Math.Max(0,r.events.Count-100)).ToList();Save(s);Append(r.message);return true;});}
  public void Finish(string status,string message){if(!new[]{"completed","partial","failed","cancelled"}.Contains(status))throw new Exception("无效任务结果。");if(activeId==null)return;LauncherNativeState.Locked(file,()=>{var s=Read();var r=s.history.FirstOrDefault(x=>x.id==activeId);if(r==null)return false;r.status=status;r.finished=DateTime.UtcNow.ToString("o");r.message=Sanitize(message);if(status=="completed")r.progress=100;else if(r.progress==100)r.progress=-1;Save(s);Append(r.title+" · "+status+" · "+r.message);activeId=null;return true;});}
  void Save(LauncherTaskStore store){if(Pending.ContainsKey(file)){try{store=Merge(ReadDisk(),store);}catch(IOException){Pending[file]=store;return;}catch(UnauthorizedAccessException){Pending[file]=store;return;}catch(InvalidDataException){Pending[file]=store;return;}}while(Encoding.UTF8.GetByteCount(LauncherNativeState.Json.Serialize(store))>1400000){if(store.history.Count>1)store.history.RemoveAt(store.history.Count-1);else if(store.history.Count==1&&store.history[0].events.Count>1)store.history[0].events.RemoveAt(0);else throw new Exception("任务记录超过容量限制。");}try{LauncherNativeState.Write(file,store);LauncherTaskStore removed;Pending.TryRemove(file,out removed);}catch(IOException){Pending[file]=store;}catch(UnauthorizedAccessException){Pending[file]=store;}}
  public void Diagnostic(string message){LauncherNativeState.Locked(file,()=>{Append(message);return true;});}
  void Append(string message){try{AppendCore(message);string removed;LogWarnings.TryRemove(file,out removed);}catch(IOException){LogWarnings[file]="部分运行日志暂未写入磁盘；不影响当前操作。";}catch(UnauthorizedAccessException){LogWarnings[file]="部分运行日志暂未写入磁盘；不影响当前操作。";}}
  void AppendCore(string message){LauncherMaintenance.NoReparse(logFile);Directory.CreateDirectory(Path.GetDirectoryName(logFile));if(File.Exists(logFile)&&new FileInfo(logFile).Length>1048576){string previous=logFile+".previous";LauncherMaintenance.NoReparse(previous);if(File.Exists(previous))File.Delete(previous);File.Move(logFile,previous);}File.AppendAllText(logFile,DateTime.UtcNow.ToString("o")+" "+Sanitize(message)+Environment.NewLine,new UTF8Encoding(false));}
  static LauncherTaskRecord SnapshotTask(LauncherTaskRecord r){return r==null?null:new LauncherTaskRecord{id=r.id,action=r.action,title=r.title,started=r.started,finished=r.finished,status=r.status,message=r.message,progress=r.progress,ownerPid=r.ownerPid,ownerBirth=r.ownerBirth,events=r.events.Select(e=>new LauncherTaskEvent{at=e.at,message=e.message,progress=e.progress}).ToList()};}
  public object Snapshot(){return LauncherNativeState.Locked(file,()=>{var s=Read();string warning;string persistenceWarning=Pending.ContainsKey(file)?"任务历史暂未保存到磁盘；当前进度与操作结果仍可在这里查看。":LogWarnings.TryGetValue(file,out warning)?warning:"";return (object)new{persistenceWarning=persistenceWarning,active=SnapshotTask(s.history.FirstOrDefault(r=>r.status=="running"&&OwnerAlive(r))),history=s.history.Take(40).Select(SnapshotTask).ToArray(),logPath=Path.GetDirectoryName(file)};});}
 }
}
